package inventory

import (
	"fmt"
	"reflect"
	"testing"
)

func TestLowStockReportFormatsEachEntry(t *testing.T) {
	useThresholdFile(t, `{}`)
	got := LowStockReport(map[string]int{"xian": 1, "chengdu": 2})
	want := []string{"xian=1", "chengdu=2"}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("LowStockReport = %v, 期望 %v", got, want)
	}
}

func TestLowStockReportMatchesWarehouseOrder(t *testing.T) {
	useThresholdFile(t, `{}`)
	stock := map[string]int{"xian": 1, "wuhan": 2, "chengdu": 2, "beijing": 99}
	low := LowStockWarehouses(stock)
	report := LowStockReport(stock)
	if len(report) != len(low) {
		t.Fatalf("LowStockReport = %v, 与 LowStockWarehouses = %v 长度不一致", report, low)
	}
	for i, warehouse := range low {
		want := fmt.Sprintf("%s=%d", warehouse, stock[warehouse])
		if report[i] != want {
			t.Fatalf("LowStockReport = %v, 第 %d 项期望 %q", report, i, want)
		}
	}
}

func TestLowStockReportEmpty(t *testing.T) {
	useThresholdFile(t, `{}`)
	if got := LowStockReport(map[string]int{}); len(got) != 0 {
		t.Fatalf("空库存应当是空报告，得到 %v", got)
	}
}
